package app.streamnest;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;
public class DiagnosticDataTest {
 @Test public void metricsNeverIncludeMediaIdentityPositionsOrCredentials()throws Exception{JSONObject d=DiagnosticData.clean(new JSONObject().put("peers",8).put("bufferedMs",7000).put("audioChannels",6).put("playState","playing").put("positionMs",123456).put("title","private").put("path","/storage/private").put("password","private").put("videoCodec","title-instead-of-codec"));assertEquals(4,d.length());assertEquals(8,d.getInt("peers"));assertFalse(d.has("positionMs"));}
 @Test public void failuresKeepSafeLocationAndHttpStatusWithoutMessageOrPath()throws Exception{java.io.IOException e=new java.io.IOException("HTTP 503 https://secret.example/path?token=private");e.setStackTrace(new StackTraceElement[]{new StackTraceElement("app.streamnest.CatalogHttp","get","private-path.java",42),new StackTraceElement("private.secret.Class","method","secret",5)});JSONObject d=DiagnosticData.failure("catalog","fetch",e);assertEquals(503,d.getInt("status"));assertEquals("IOException",d.getString("errorClass"));assertEquals("app.streamnest.CatalogHttp.get:42",d.getJSONArray("frames").getString(0));String bytes=d.toString();assertFalse(bytes.contains("secret"));assertFalse(bytes.contains("https"));assertFalse(bytes.contains("private"));assertEquals(1,d.getJSONArray("frames").length());}
 @Test public void causesAndCodecNamesAreBounded()throws Exception{Exception e=new java.io.IOException("redacted",new java.net.UnknownHostException("private-host"));JSONObject d=DiagnosticData.failure("catalog","fetch",e);assertEquals("UnknownHostException",d.getString("causeClass"));assertEquals("network",d.getString("reason"));assertEquals("h264",DiagnosticData.codec("avc1",false));assertEquals("aac",DiagnosticData.codec("mp4a",true));assertEquals("unknown",DiagnosticData.codec("private title",true));assertFalse(DiagnosticData.clean(new JSONObject().put("peers",-1).put("bufferedMs",1.5).put("errorClass","secret/path")).keys().hasNext());}
}
